/**
 * The console icon from Material Design Icons (mdi-console), Apache 2.0.
 *
 * Kept as a data URI like every other icon here, so the worker can inline it
 * and the page costs no extra request. SVG rather than the PNGs around it:
 * it is a line drawing and stays sharp at every ico-NN size.
 */
export const mdi_console = `data:image/svg+xml;base64,`
